# FIX: grid uses lambda so autotune XBLOCK propagates correctly
@triton.autotune(configs=[
    Config({'XBLOCK': 1},   num_warps=1, num_stages=1),
    ...,
    Config({'XBLOCK': 32},  num_warps=4, num_stages=1),
    Config({'XBLOCK': 64},  num_warps=4, num_stages=1),  # NEW
    Config({'XBLOCK': 128}, num_warps=4, num_stages=1),  # NEW
], key=[...])
@triton.jit
def kernel(in_out_ptr0, in_ptr0, xnumel, r0_numel, XBLOCK: tl.constexpr):
    ...

def kernel_function(*inputs):
    xnumel = 128
    grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # FIX
    kernel[grid](arg_0, arg_1, 128, 6)  # do NOT pass XBLOCK= explicitly
